Here's a self-contained Python function that returns items that appear exactly once (preserving order). It uses pydantic v2 (released in 2023) for optional input validation. The function handles both hashable and unhashable elements efficiently (avoiding O(n^2) work for hashable elements while still correctly counting unhashable ones).

Note: install pydantic v2+ if you don't have it: pip install "pydantic>=2.0"

```python
from typing import Any, List
from pydantic import BaseModel


def unique_once(items: List[Any]) -> List[Any]:
    """
    Return a new list containing only the elements from `items` that appear exactly once,
    preserving their original order.

    Uses pydantic (v2+) to validate input shape. Handles both hashable and unhashable items.

    Example:
        >>> unique_once([1, 2, 2, 3, [4], [4], (5,), (5,), 6])
        [1, 3, 6]
    """
    # Validate input shape (optional but demonstrates use of a 2023+ library: pydantic v2)
    class InputModel(BaseModel):
        items: List[Any]

    validated = InputModel(items=items).items

    # Count hashable items using a dict => O(n) for these elements
    hash_counts = {}
    # Track unhashable items and their counts using equality checks (small list expected)
    unhashable_list = []  # list of tuples: (value, count)

    for el in validated:
        try:
            # If this raises TypeError, the element is unhashable
            hash_counts[el] = hash_counts.get(el, 0) + 1
        except TypeError:
            # linear scan among seen unhashables (compare by ==)
            for i, (val, cnt) in enumerate(unhashable_list):
                if val == el:
                    unhashable_list[i] = (val, cnt + 1)
                    break
            else:
                unhashable_list.append((el, 1))

    # Build result preserving original order
    result: List[Any] = []
    for el in validated:
        try:
            if hash_counts.get(el, 0) == 1:
                result.append(el)
        except TypeError:
            # unhashable: find its count in unhashable_list via equality
            for val, cnt in unhashable_list:
                if val == el:
                    if cnt == 1:
                        result.append(el)
                    break

    return result
```

