                    current = current / denom if denom != 0 else current
                i += 1
                continue

            # units and tens
            if tok in UNITS:
                current += UNITS[tok]
                i += 1
                continue
            if tok in TENS:
                current += TENS[tok]
                i += 1
                continue

            # scale words like hundred, thousand, million
            if tok in SCALES:
                scale = SCALES[tok]
                if tok == 'hundred':
                    # hundred multiplies current (or 1 if current==0)
                    if current == 0:
                        current = 1
                    current *= scale
                else:
