from typing import List, Dict, Any, Tuple, Union
import polars as pl

Condition = Union[
    Tuple[str, str, Any],  # ("col", "op", value)
    Dict[str, Any]         # {"col": "...", "op": "...", "value": ...}
]

def filter_table(
    table: Union[List[Dict[str, Any]], List[List[Any]]],
    columns: List[str] = None,
    conditions: List[Condition] = None,
    combine: str = "and",
    return_dataframe: bool = False,
) -> Union[List[Dict[str, Any]], pl.DataFrame]:
    """
    Filter a 2D table by multiple conditions using polars.

    Parameters:
    - table: list of dicts (rows) or list of lists (rows). If list of lists, `columns` must be provided.
    - columns: list of column names (required if table is list of lists).
    - conditions: list of conditions. Each condition may be:
        - tuple: (col, op, value) e.g. ("age", ">", 30)
        - dict: {"col": "age", "op": ">", "value": 30}
      Supported ops: "==","=","eq","!=","<>","ne", "<", "<=", ">", ">=",
                     "in", "not in", "like" (substring/regex), "ilike" (case-insensitive substring),
                     "isnull", "notnull"
      For "in"/"not in", provide value as a sequence (list/tuple/set).
      For "isnull"/"notnull", the value is ignored.
    - combine: "and" (default) or "or" to combine multiple conditions.
    - return_dataframe: if True, return a polars.DataFrame; otherwise return list of dicts.

    Returns:
    - Filtered rows as list of dicts or polars.DataFrame if return_dataframe True.

    Example:
    rows = [
        {"name": "Alice", "age": 30, "city": "NY"},
        {"name": "Bob",   "age": 22, "city": "LA"},
        {"name": "Cathy", "age": 35, "city": "NY"},
    ]
    conds = [("city", "==", "NY"), ("age", ">", 30)]
    filtered = filter_table(rows, conditions=conds)
    # returns [{"name":"Cathy","age":35,"city":"NY"}]
    """
    if conditions is None:
        conditions = []

    # Build DataFrame
    if isinstance(table, list) and len(table) > 0 and isinstance(table[0], dict):
        df = pl.DataFrame(table)
    else:
        # assume list-of-lists
        if columns is None:
            raise ValueError("When table is a list-of-lists, 'columns' must be provided.")
        df = pl.DataFrame(table, schema=columns)

    if not conditions:
        return df if return_dataframe else df.to_dicts()

    # Helper to normalize condition into (col, op, value)
    def _normalize(cond: Condition):
        if isinstance(cond, dict):
            col = cond.get("col")
            op = cond.get("op")
            val = cond.get("value", None)
        elif isinstance(cond, tuple) or isinstance(cond, list):
            if len(cond) != 3:
                raise ValueError("Tuple/list condition must be (col, op, value)")
            col, op, val = cond
        else:
            raise ValueError("Condition must be tuple or dict")
        if not isinstance(op, str):
            op = str(op)
        return col, op.lower(), val

    # Build polars expressions
    exprs = []
    for cond in conditions:
        col, op, val = _normalize(cond)

        if op in ("==", "=", "eq"):
            e = pl.col(col) == val
        elif op in ("!=", "<>", "ne"):
            e = pl.col(col) != val
        elif op == "<":
            e = pl.col(col) < val
        elif op == "<=":
            e = pl.col(col) <= val
        elif op == ">":
            e = pl.col(col) > val
        elif op == ">=":
            e = pl.col(col) >= val
        elif op == "in":
            # val should be an iterable of allowed values
            e = pl.col(col).is_in(val)
        elif op == "not in":
            e = ~pl.col(col).is_in(val)
        elif op == "like":
            # substring or regex match
            # if val is not a str, cast it
            e = pl.col(col).cast(pl.Utf8).str.contains(str(val))
        elif op == "ilike":
            # case-insensitive substring match
            e = pl.col(col).cast(pl.Utf8).str.to_lower().str.contains(str(val).lower())
        elif op in ("isnull", "is_null"):
            e = pl.col(col).is_null()
        elif op in ("notnull", "not_null"):
            e = ~pl.col(col).is_null()
        else:
            raise ValueError(f"Unsupported operator: {op}")
        exprs.append(e)

    # Combine expressions
    if combine not in ("and", "or"):
        raise ValueError("combine must be 'and' or 'or'")

    combined = exprs[0]
    for ex in exprs[1:]:
        combined = combined & ex if combine == "and" else combined | ex

    filtered = df.filter(combined)

    return filtered if return_dataframe else filtered.to_dicts()
