    - If multiple original keys lower to the same string, the last occurrence (in the original mapping's iteration order)
      wins for lookups.
    - Values that are:
      - strings -> returned lowercased
      - mappings -> wrapped as a LazyLowerDict (lazy, same behavior)
      - lists/tuples -> their elements are recursively lowered (returned as same sequence type)
      - others -> returned unchanged
    - The returned object is read-only (Mapping).
    """
    from collections.abc import Mapping
    from typing import Any, Iterator

    try:
        # pydantic v2 provides TypeAdapter (released 2023)
        from pydantic import TypeAdapter
    except Exception as e:
        raise RuntimeError(
            "This function requires pydantic v2 (released in 2023). "
            "Install/upgrade with: pip install 'pydantic>=2'"
        ) from e

    # Validate the provided value is a mapping with string keys
    TypeAdapter(Mapping[str, Any]).validate_python(dict0)

    class LazyLowerDict(Mapping):
        def __init__(self, original: Mapping[str, Any]):
            self._original = original
            # index maps lowercase key -> last-seen original key (keeps O(1) lookups)
            self._index = {}
            for k in original:
                if not isinstance(k, str):
                    raise TypeError("All keys must be strings to lowercase")
                self._index[k.lower()] = k

        def __getitem__(self, key: str) -> Any:
            if not isinstance(key, str):
                raise KeyError(key)
            lk = key.lower()
            orig_key = self._index.get(lk)
            if orig_key is None:
                raise KeyError(key)
            val = self._original[orig_key]
            return self._lower_value(val)

        def __iter__(self) -> Iterator[str]:
            # Preserve insertion order of first-seen lowercase keys
            seen = set()
            for k in self._original:
                lk = k.lower()
                if lk in seen:
                    continue
                seen.add(lk)
                yield lk

        def __len__(self) -> int:
            return len(self._index)

        def _lower_value(self, v):
            # Recursively lower values where appropriate
            if isinstance(v, str):
                return v.lower()
            if isinstance(v, Mapping):
                return LazyLowerDict(v)
            if isinstance(v, list):
                return [self._lower_value(x) for x in v]
            if isinstance(v, tuple):
                return tuple(self._lower_value(x) for x in v)
            return v

        def __repr__(self):
            # Represent by materializing items for readability only
            return f"{self.__class__.__name__}({dict(self.items())})"

