            except Exception as e:
                raise ValueError(f"Failed to evaluate combined query '{combined_query}': {e}")

        # Otherwise treat as list of dicts / nested items and combine respecting connectors
        masks: List[pd.Series] = []
        connectors: List[str] = []
        for idx, item in enumerate(var0):
            mask = _mask_from_filter_item(item)
