from typing import Iterable, List
from pydantic import BaseModel, field_validator

class SeqModel(BaseModel):
    seq: List[int]

    # ensure we have at least two integers and they are ints
    @field_validator('seq')
    @classmethod
    def validate_seq(cls, v):
        # allow any iterable by converting to list
        if not isinstance(v, list):
            v = list(v)
        if len(v) < 2:
            raise ValueError("sequence must contain at least two elements")
        if not all(isinstance(x, int) for x in v):
            raise TypeError("all elements must be integers")
        return v

def max_consecutive_diff(seq: Iterable[int], signed: bool = False) -> int:
    """
    Return the maximum difference between consecutive elements in `seq`.

    By default returns the maximum absolute difference:
      max(|seq[i] - seq[i-1]| for i in 1..n-1)

    If signed=True, returns the maximum signed difference:
      max(seq[i] - seq[i-1] for i in 1..n-1)

    Raises ValueError/TypeError if input is invalid (via pydantic validation).
    """
    model = SeqModel(seq=seq)      # validates and converts to list[int]
    s = model.seq
    if signed:
        return max(s[i] - s[i-1] for i in range(1, len(s)))
    else:
        return max(abs(s[i] - s[i-1]) for i in range(1, len(s)))

# Examples:
# max_consecutive_diff([1, 4, 2, 10]) -> max(|4-1|=3, |2-4|=2, |10-2|=8) = 8
# max_consecutive_diff([5, 3, 9], signed=True) -> max(3-5=-2, 9-3=6) = 6
