def df_to_dicts(df):
    """
    Convert a tabular dataset `df` into a list of dictionaries (one dict per row).
    Supports polars.DataFrame, pandas.DataFrame, pyarrow.Table, list-of-dicts,
    or other inputs convertible to a Polars DataFrame.

    Requires polars (recommended version >= 0.18.0). Install with:
        pip install "polars>=0.18.0"

    Returns:
        list of dict
    """
    try:
        import polars as pl
    except ImportError as e:
        raise ImportError(
            'polars is required for df_to_dicts. Install with: pip install "polars>=0.18.0"'
        ) from e

    # If already a Polars DataFrame
    if isinstance(df, pl.DataFrame):
        return df.to_dicts()

    # If pandas DataFrame, convert via Polars for robust handling
    try:
        import pandas as pd
    except Exception:
        pd = None

    if pd is not None and isinstance(df, pd.DataFrame):
        return pl.from_pandas(df).to_dicts()

    # If PyArrow Table, convert via Polars
    try:
        import pyarrow as pa
    except Exception:
        pa = None

    if pa is not None and isinstance(df, pa.Table):
        return pl.from_arrow(df).to_dicts()

    # If already a list of dicts, return as-is (defensive copy)
    if isinstance(df, list) and all(isinstance(r, dict) for r in df):
        return [dict(r) for r in df]

    # Try constructing a Polars DataFrame from the input (handles lists of tuples, dict of lists, etc.)
    try:
        return pl.DataFrame(df).to_dicts()
    except Exception as e:
        raise TypeError(
            "Unsupported input type for df_to_dicts. Supported: polars.DataFrame, pandas.DataFrame, pyarrow.Table, list-of-dicts, or inputs convertible to a Polars DataFrame."
        ) from e

