from typing import Any, Mapping, Sequence
from pydantic import TypeAdapter, ValidationError

def keys_with_values_containing(dict0: Any, lst0: Any) -> list:
    """
    Return all keys from mapping `dict0` whose associated values contain at least
    one element from sequence `lst0`.

    Behavior and edge cases:
    - Uses pydantic (v2+, released 2023) for light input validation/coercion.
    - Treats strings and bytes as atomic values (not iterables of characters).
    - If a value is not an iterable (e.g., an int), it is treated as a single-element sequence.
    - Preserves the order of keys as they appear in the given mapping (if the mapping is ordered).
    - Works with unhashable elements in either the mapping values or lst0 (falls back to equality checks).

    Parameters:
    - dict0: mapping-like input (will be validated/coerced by pydantic).
    - lst0: sequence-like input (will be validated/coerced by pydantic).

    Returns:
    - list of keys from dict0 meeting the criterion.

    Example:
    >>> keys_with_values_containing({'a': [1,2], 'b': (3,4), 'c': 5}, [2,5])
    ['a', 'c']
    """
    # Validate/coerce inputs to mapping and sequence using pydantic TypeAdapter (pydantic v2+)
    try:
        ta_map = TypeAdapter(Mapping[Any, Any])
        ta_seq = TypeAdapter(Sequence[Any])
        mapping = ta_map.validate_python(dict0)
        seq = list(ta_seq.validate_python(lst0))  # convert to list for potential repeated equality checks
    except ValidationError as exc:
        raise TypeError(f"Invalid input types: {exc}") from exc

    # Try to prepare a fast membership test if seq is hashable
    try:
        seq_set = set(seq)
        use_set = True
    except TypeError:
        seq_set = None
        use_set = False

    result_keys = []
    for k, v in mapping.items():
        # Normalize v to a sequence if it isn't one, treat str/bytes as atomic
        if isinstance(v, (str, bytes)):
            candidates = [v]
        else:
            # If it's a sequence (like list/tuple), keep it; otherwise treat as single element
            if isinstance(v, Sequence):
                candidates = list(v)
            else:
                candidates = [v]

        found = False
        if use_set:
            for item in candidates:
                try:
                    if item in seq_set:
                        found = True
                        break
                except TypeError:
                    # Unhashable item: fall back to equality checks for this item
                    for s in seq:
                        if item == s:
                            found = True
                            break
                    if found:
                        break
        else:
            # seq contains unhashable elements; do nested equality checks
            for item in candidates:
                for s in seq:
                    if item == s:
                        found = True
                        break
                if found:
                    break

        if found:
            result_keys.append(k)

    return result_keys

# Minimal self-test when run as a script
if __name__ == "__main__":
    print(keys_with_values_containing({'a': [1,2], 'b': (3,4), 'c': "hello", 'd': 5}, [2, "x", 5]))  # ['a', 'd']
    print(keys_with_values_containing({'x': [[1], 2], 'y': [{'z': 3}]}, [[1]]))  # ['x']

