def lowercase_mapping(mapping: dict) -> dict:
    """
    Convert all keys and values in a mapping to lowercase using a generator expression.

    Uses a dictionary comprehension with generator-like syntax to transform
    both keys and values to lowercase strings.

    Args:
        mapping: A dictionary with string keys and values

    Returns:
        A new dictionary with all keys and values converted to lowercase

    Example:
        >>> result = lowercase_mapping({'Name': 'John', 'City': 'NEW YORK'})
