def divide_common_keys(dict0: dict[K, V], dict1: dict[K, V]) -> dict[K, float]:
    """
    For keys present in both dict0 and dict1, return a new dict with 
    dict0's value divided by dict1's value for each common key.

    Args:
        dict0: First dictionary with numeric values
        dict1: Second dictionary with numeric values

    Returns:
        Dictionary with common keys and division results

    Raises:
        ZeroDivisionError: If any value in dict1 is zero
        TypeError: If values are not numeric
    """
    # Find common keys using set intersection
    common_keys = dict0.keys() & dict1.keys()

    # Create result dictionary with division for each common key
    result = {}
    for key in common_keys:
        numerator = dict0[key]
        denominator = dict1[key]

        if denominator == 0:
            raise ZeroDivisionError(f"Division by zero for key '{key}'")

        result[key] = numerator / denominator

    return result


